{
  "version": "Notebook/1.0",
  "items": [
    {
      "type": 1,
      "content": {
        "json": "## CTL Agent  Verdict Evidence & Audit Trail\n\nEnd-to-end audit trail for every Clear-To-List evaluation. Pick a **Session** below to see the orchestrator phases, sub-agent reasoning, MCP tool calls, RAG citations, and the final verdict  with its evidence chain.\n\n*Source: `AppEvents` (event = `CTL.AuditStep`) emitted by the CTL Agent Host into Application Insights `ctlagent-appinsights`.*"
      },
      "name": "header"
    },
    {
      "type": 9,
      "content": {
        "version": "KqlParameterItem/1.0",
        "parameters": [
          {
            "id": "p-timerange",
            "version": "KqlParameterItem/1.0",
            "name": "TimeRange",
            "label": "Time range",
            "type": 4,
            "isRequired": true,
            "value": { "durationMs": 2592000000 },
            "typeSettings": {
              "selectableValues": [
                { "durationMs": 3600000 },
                { "durationMs": 86400000 },
                { "durationMs": 604800000 },
                { "durationMs": 2592000000 },
                { "durationMs": 7776000000 }
              ]
            }
          },
          {
            "id": "p-session",
            "version": "KqlParameterItem/1.0",
            "name": "SessionId",
            "label": "Session",
            "type": 2,
            "isRequired": true,
            "query": "AppEvents\n| where Name == 'CTL.AuditStep'\n| extend SessionId = tostring(Properties.SessionId), AssetId = tostring(Properties.AssetId)\n| summarize Started = min(TimeGenerated), Steps = count(), AssetId = anyif(AssetId, AssetId != '' and isnotempty(AssetId)) by SessionId\n| order by Started desc\n| project value = SessionId, label = strcat(SessionId, '      ', coalesce(AssetId, ''), '      ', format_datetime(Started, 'yyyy-MM-dd HH:mm:ss'), ' UTC      ', tostring(Steps), ' steps')",
            "typeSettings": { "additionalResourceOptions": [] },
            "timeContext": { "durationMs": 0 },
            "timeContextFromParameter": "TimeRange",
            "queryType": 0,
            "resourceType": "microsoft.insights/components"
          }
        ],
        "style": "pills",
        "queryType": 0,
        "resourceType": "microsoft.insights/components"
      },
      "name": "parameters"
    },
    {
      "type": 1,
      "content": {
        "json": "### Verdict Summary"
      },
      "name": "summary-header"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "AppEvents\n| where Name == 'CTL.AuditStep'\n| where tostring(Properties.SessionId) == '{SessionId}'\n| extend Step = tostring(Properties.StepType), Description = tostring(Properties.Description), AssetId = tostring(Properties.AssetId), Agent = tostring(Properties.AgentName)\n| summarize\n    Asset = anyif(AssetId, AssetId != '' and isnotempty(AssetId)),\n    Started = min(TimeGenerated),\n    Completed = max(TimeGenerated),\n    Steps = count(),\n    Verdict = anyif(Description, Step == 'EvaluationCompleted'),\n    HumanReview = countif(Step in ('HumanReviewRequested','HumanReviewSubmitted')) > 0,\n    SafetyDegraded = countif(Step in ('ContentSafetyDegraded','CircuitBreakerOpen')) > 0,\n    Failures = countif(Step == 'AgentExhaustedRetries')\n| extend DurationSec = datetime_diff('second', Completed, Started)\n| project Asset, Started, DurationSec, Steps, Verdict, HumanReview, SafetyDegraded, Failures",
        "size": 3,
        "queryType": 0,
        "resourceType": "microsoft.insights/components",
        "visualization": "table",
        "gridSettings": {
          "formatters": [
            {
              "columnMatch": "Verdict",
              "formatter": 1
            },
            {
              "columnMatch": "HumanReview",
              "formatter": 18,
              "formatOptions": {
                "thresholdsOptions": "icons",
                "thresholdsGrid": [
                  { "operator": "==", "thresholdValue": "true", "representation": "warning", "text": "Yes" },
                  { "operator": "Default", "representation": "success", "text": "No" }
                ]
              }
            },
            {
              "columnMatch": "SafetyDegraded",
              "formatter": 18,
              "formatOptions": {
                "thresholdsOptions": "icons",
                "thresholdsGrid": [
                  { "operator": "==", "thresholdValue": "true", "representation": "failed", "text": "Yes" },
                  { "operator": "Default", "representation": "success", "text": "No" }
                ]
              }
            }
          ]
        }
      },
      "name": "verdict-summary"
    },
    {
      "type": 1,
      "content": {
        "json": "### Phase Timeline\n\nDuration of each orchestrator phase (Planning  Investigation  Reflection  Quality Gate)."
      },
      "name": "timeline-header"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "AppEvents\n| where Name == 'CTL.AuditStep'\n| where tostring(Properties.SessionId) == '{SessionId}'\n| extend Agent = tostring(Properties.AgentName), Step = tostring(Properties.StepType)\n| where Agent startswith 'CTLOrchestrator-' or Agent == 'CTLWorkflowOrchestrator'\n| where Step in ('PhaseStarted','PhaseCompleted','EvaluationCompleted','AssetProfileSupplied')\n| project TimeGenerated, Phase = replace_string(Agent, 'CTLOrchestrator-', ''), Step, Description = tostring(Properties.Description)\n| order by TimeGenerated asc",
        "size": 0,
        "queryType": 0,
        "resourceType": "microsoft.insights/components",
        "visualization": "table"
      },
      "name": "phase-timeline"
    },
    {
      "type": 1,
      "content": {
        "json": "### Audit Trail  every step\n\nClick the  on any row to expand it as a card (no horizontal scroll).\n\n**Legend:** `[Orchestrator  Deterministic]` = workflow control  `[LLM ...]` = model reasoning  `[LLM Tool Call]` = MCP tool invocation  `[Guardrail  ...]` = safety filter  `[Human Review]` = manual reviewer."
      },
      "name": "trail-header"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "AppEvents\n| where Name == 'CTL.AuditStep'\n| where tostring(Properties.SessionId) == '{SessionId}'\n| extend Time  = format_datetime(TimeGenerated, 'HH:mm:ss.fff'),\n         Agent = tostring(Properties.AgentName),\n         Step  = tostring(Properties.StepType),\n         Description = tostring(Properties.Description),\n         Payload     = tostring(Properties.OutputPayload),\n         Tokens      = todouble(Measurements.TokensUsed),\n         DurationMs  = todouble(Measurements.DurationMs)\n| project TimeGenerated, Time, Agent, Step, Description, Tokens, DurationMs, Payload\n| order by TimeGenerated asc",
        "size": 0,
        "queryType": 0,
        "resourceType": "microsoft.insights/components",
        "visualization": "table",
        "gridSettings": {
          "rowLimit": 1000,
          "formatters": [
            {
              "columnMatch": "TimeGenerated",
              "formatter": 5
            },
            {
              "columnMatch": "Description",
              "formatter": 1
            },
            {
              "columnMatch": "Payload",
              "formatter": 7,
              "formatOptions": {
                "linkTarget": "CellDetails",
                "linkLabel": "View payload"
              }
            }
          ]
        }
      },
      "name": "audit-trail"
    },
    {
      "type": 1,
      "content": {
        "json": "### Tool Calls & RAG Citations"
      },
      "name": "tools-header"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "AppEvents\n| where Name == 'CTL.AuditStep'\n| where tostring(Properties.SessionId) == '{SessionId}'\n| where tostring(Properties.StepType) == 'ToolCallExecuted'\n| extend Time = format_datetime(TimeGenerated, 'HH:mm:ss.fff'),\n         Agent = tostring(Properties.AgentName),\n         Description = tostring(Properties.Description),\n         Payload     = tostring(Properties.OutputPayload)\n| project TimeGenerated, Time, Agent, Description, Payload\n| order by TimeGenerated asc",
        "size": 0,
        "queryType": 0,
        "resourceType": "microsoft.insights/components",
        "visualization": "table",
        "gridSettings": {
          "rowLimit": 500,
          "formatters": [
            {
              "columnMatch": "Description",
              "formatter": 1
            },
            {
              "columnMatch": "Payload",
              "formatter": 7,
              "formatOptions": {
                "linkTarget": "CellDetails",
                "linkLabel": "View tool I/O"
              }
            }
          ]
        }
      },
      "name": "tool-calls"
    },
    {
      "type": 1,
      "content": {
        "json": "### Guardrails  safety screening events\n\nContent Safety, Prompt Shields, PII filter, Token Budget. Each row proves a guardrail ran on every input/output."
      },
      "name": "guard-header"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "AppEvents\n| where Name == 'CTL.AuditStep'\n| where tostring(Properties.SessionId) == '{SessionId}'\n| where tostring(Properties.AgentName) startswith 'GuardrailsMiddleware'\n| extend Time = format_datetime(TimeGenerated, 'HH:mm:ss.fff'),\n         Agent = tostring(Properties.AgentName),\n         Step  = tostring(Properties.StepType),\n         Description = tostring(Properties.Description)\n| project TimeGenerated, Time, Agent, Step, Description\n| order by TimeGenerated asc",
        "size": 0,
        "queryType": 0,
        "resourceType": "microsoft.insights/components",
        "visualization": "table",
        "gridSettings": {
          "rowLimit": 500,
          "formatters": [
            {
              "columnMatch": "Description",
              "formatter": 1
            }
          ]
        }
      },
      "name": "guardrails"
    },
    {
      "type": 1,
      "content": {
        "json": "### Recent sessions (cross-session view)"
      },
      "name": "recent-header"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "AppEvents\n| where Name == 'CTL.AuditStep'\n| extend SessionId = tostring(Properties.SessionId),\n         AssetId   = tostring(Properties.AssetId),\n         Step      = tostring(Properties.StepType),\n         Description = tostring(Properties.Description)\n| summarize\n    Asset      = anyif(AssetId, AssetId != '' and isnotempty(AssetId)),\n    Started    = min(TimeGenerated),\n    Steps      = count(),\n    Verdict    = anyif(Description, Step == 'EvaluationCompleted'),\n    Failures   = countif(Step == 'AgentExhaustedRetries')\n  by SessionId\n| order by Started desc\n| take 50",
        "size": 0,
        "queryType": 0,
        "resourceType": "microsoft.insights/components",
        "visualization": "table",
        "gridSettings": {
          "rowLimit": 50,
          "formatters": [
            {
              "columnMatch": "Verdict",
              "formatter": 1
            }
          ]
        }
      },
      "name": "recent-sessions"
    }
  ],
  "fallbackResourceIds": [],
  "$schema": "https://github.com/Microsoft/Application-Insights-Workbooks/blob/master/schema/workbook.json"
}
